// Desktop shell (Windows / Linux) generated by tools/build/build.js.
// The game runs from the app:// protocol so ES modules and fetch() of data files work as on a
// web server; files missing in the package (e.g. /api/...) answer 404 and the game falls back
// to local storage.
const { app, BrowserWindow, protocol, net, Menu } = require('electron');
const path = require('path');
const { pathToFileURL } = require('url');
const settings = require('./app-settings.json');

protocol.registerSchemesAsPrivileged([{
    scheme: 'app',
    privileges: { standard: true, secure: true, supportFetchAPI: true, corsEnabled: true, stream: true }
}]);

const ROOT = path.join(__dirname, 'www');

app.whenReady().then(() => {
    protocol.handle('app', async (request) => {
        try {
            let p = decodeURIComponent(new URL(request.url).pathname);
            if (p === '/' || p === '') p = '/index.html';
            const file = path.normalize(path.join(ROOT, p));
            if (!file.startsWith(ROOT)) return new Response('forbidden', { status: 403 });
            return await net.fetch(pathToFileURL(file).toString());
        } catch (e) {
            return new Response('not found', { status: 404 });
        }
    });

    Menu.setApplicationMenu(null);
    const win = new BrowserWindow({
        width: settings.width || 1280,
        height: settings.height || 960,
        title: settings.title || 'Game',
        backgroundColor: '#000000',
        icon: path.join(__dirname, 'icon.png'),
        autoHideMenuBar: true,
        webPreferences: { contextIsolation: true, sandbox: true }
    });
    // F11 = full screen, Esc leaves it
    win.webContents.on('before-input-event', (event, input) => {
        if (input.type !== 'keyDown') return;
        if (input.key === 'F11') { win.setFullScreen(!win.isFullScreen()); event.preventDefault(); }
        else if (input.key === 'Escape' && win.isFullScreen()) { win.setFullScreen(false); }
    });
    win.loadURL('app://game/index.html');
});

app.on('window-all-closed', () => app.quit());
